      "text": "    out = pd.Series(False, index=df.index)"
    },
    {
      "number": 54,
      "text": "    if not _require(df, 70):"
    },
    {
      "number": 55,
      "text": "        return out"
    },
    {
      "number": 56,
      "text": "    c, hi, lo = df[\"close\"], df[\"high\"], df[\"low\"]"
    },
    {
      "number": 57,
      "text": "    v = df[\"volume\"]"
    },
    {
      "number": 58,
      "text": "    multi = ind.multi_head(df).to_numpy()"
    },
    {
      "number": 59,
      "text": "    vol_ratio = ind.vol_shrink_ratio(df).to_numpy()"
    },
    {
      "number": 60,
      "text": "    ma20 = ind.ma(c, 20).to_numpy()"
    },
    {
      "number": 61,
      "text": "    ma20_rising = ma20 > pd.Series(ma20).shift(5).to_numpy()"
    },
    {
      "number": 62,
      "text": "    n = len(df)"
    },
    {
      "number": 63,
      "text": "    if mode == \"screen\":"
    },
    {
      "number": 64,
      "text": "        d_min, d_max = int(CFG_HG.get(\"pullback_days_min\", 3)), int(CFG_HG.get(\"pullback_days_max\", 5))"
    },
    {
      "number": 65,
      "text": "        p_min, p_max = float(CFG_HG.get(\"pullback_pct_min\", 5.0)), float(CFG_HG.get(\"pullback_pct_max\", 15.0))"
    },
    {
      "number": 66,
      "text": "        shrink = float(CFG_HG.get(\"volume_shrink_ratio\", 0.7))"
    },
    {
      "number": 67,
      "text": "        for i in range(70, n):"
    },
    {
      "number": 68,
      "text": "            if not multi[i]:"
    },
    {
      "number": 69,
      "text": "                continue"
    },
    {
      "number": 70,
      "text": "            window = hi.iloc[i - 20:i]"
    },
    {
      "number": 71,
      "text": "            hh = float(window.max())"
    },
    {
      "number": 72,
      "text": "            if hh <= 0 or c.iloc[i] / hh >= 0.95:"
    },
    {
      "number": 73,
      "text": "                continue"
    },
    {
      "number": 74,
      "text": "            back_days = i - (i - 20 + int(window.values.argmax()))"
    },
    {
      "number": 75,
      "text": "            pull = (hh - c.iloc[i]) / hh * 100"
    },
    {
      "number": 76,
      "text": "            if d_min <= back_days <= d_max and p_min <= pull <= p_max and vol_ratio[i] < shrink:"
    },
    {
      "number": 77,
      "text": "                out.iloc[i] = True"
    },
    {
      "number": 78,
      "text": "        return out"
    },
    {
      "number": 79,
      "text": "    # live 口径（v4.0.1 案例回归校准：回调幅度 1~15%、量能口径改为「回调期日均量 vs 拉升峰值量」）"
    },
    {
      "number": 80,
      "text": "    live = dict(CFG_HG.get(\"live\", {}))"
    },
    {
      "number": 81,
      "text": "    if overrides:"
    },
    {
      "number": 82,
      "text": "        live.update(overrides)"
    },
    {
      "number": 83,
      "text": "    d_min = int(live.get(\"pullback_days_min\", 1))"
    },
    {
      "number": 84,
      "text": "    d_max = int(live.get(\"pullback_days_max\", 7))"
    },
    {
      "number": 85,
      "text": "    p_min = float(live.get(\"pullback_pct_min\", 1.0))"
    },
    {
      "number": 86,
      "text": "    p_max = float(live.get(\"pullback_pct_max\", 15.0))"
    },
    {
      "number": 87,
      "text": "    vol_ratio_max = float(live.get(\"volume_ratio_max\", 0.9))"
    },
    {
      "number": 88,
      "text": "    prior_gain_min = float(live.get(\"prior_gain_min_pct\", 8.0))"
    },
    {
      "number": 89,
      "text": "    for i in range(70, n):"
    },
    {
      "number": 90,
      "text": "        if c.iloc[i] <= ma20[i] or not bool(ma20_rising[i]):"
    },
    {
      "number": 91,
      "text": "            continue"
    },
    {
      "number": 92,
      "text": "        window = hi.iloc[i - 10:i]"
    },
    {
      "number": 93,
      "text": "        hh = float(window.max())"
    },
    {
      "number": 94,
      "text": "        if hh <= 0:"
    },
    {
      "number": 95,
      "text": "            continue"
    },
    {
      "number": 96,
      "text": "        peak_pos = int(window.values.argmax())  # 拉升峰值日（相对窗口起点）"
    },
    {
      "number": 97,
      "text": "        peak_idx = i - 10 + peak_pos"
    },
    {
      "number": 98,
      "text": "        back_days = i - peak_idx"
    },
    {
      "number": 99,
      "text": "        pull = (hh - c.iloc[i]) / hh * 100"
    },
    {
      "number": 100,
      "text": "        if not (d_min <= back_days <= d_max):"
    },
    {
      "number": 101,
      "text": "            continue"
    },
    {
      "number": 102,
      "text": "        if not (p_min <= pull <= p_max):"
    },
    {
      "number": 103,
      "text": "            continue"
    },
    {
      "number": 104,
      "text": "        # 量能：回调期日均量 vs 拉升峰值日±1天最大量（视频口径「相对拉升缩量」）"
    },
    {
      "number": 105,
      "text": "        if peak_idx < 1:"
    },
    {
      "number": 106,
      "text": "            continue"
    },
    {
      "number": 107,
      "text": "        peak_vol = float(v.iloc[max(0, peak_idx - 1):min(n, peak_idx + 2)].max())"
    },
    {
      "number": 108,
      "text": "        if peak_vol <= 0:"
    },
    {
      "number": 109,
      "text": "            continue"
    },
    {
      "number": 110,
      "text": "        pullback_vol = float(v.iloc[peak_idx + 1:i + 1].mean())"
    },
    {
      "number": 111,
      "text": "        if pullback_vol / peak_vol >= vol_ratio_max:"
    },
    {
      "number": 112,
      "text": "            continue"
    },
    {
      "number": 113,
      "text": "        # 前期一波上涨：近10日高点相对 20 日前收盘的涨幅"
    },
    {
      "number": 114,
      "text": "        if i < 20 or hh / c.iloc[i - 20] - 1 < prior_gain_min / 100.0:"
    },
    {
      "number": 115,
      "text": "            continue"
    },
    {
      "number": 116,
      "text": "        out.iloc[i] = True"
    },
    {
      "number": 117,
      "text": "    return out"
    },
    {
      "number": 118,
      "text": ""
    },
