    {
      "number": 120,
      "text": "def detect_zt_huicai(df: pd.DataFrame) -> pd.Series:"
    },
    {
      "number": 121,
      "text": "    \"\"\"涨停回踩低吸（简化 3 条件）："
    },
    {
      "number": 122,
      "text": "    近 2~7 天内出现过涨停，回踩不破涨停日最低价，价站 5 日线与 20 日线上方，量缩\"\"\""
    },
    {
      "number": 123,
      "text": "    out = pd.Series(False, index=df.index)"
    },
    {
      "number": 124,
      "text": "    if not _require(df, 30):"
    },
    {
      "number": 125,
      "text": "        return out"
    },
    {
      "number": 126,
      "text": "    c, lo = df[\"close\"], df[\"low\"]"
    },
    {
      "number": 127,
      "text": "    v = df[\"volume\"]"
    },
    {
      "number": 128,
      "text": "    zt = ind.limit_up_mask(df).to_numpy()"
    },
    {
      "number": 129,
      "text": "    vol_ratio = ind.vol_shrink_ratio(df).to_numpy()"
    },
    {
      "number": 130,
      "text": "    ma5 = ind.ma(c, 5).to_numpy()"
    },
    {
      "number": 131,
      "text": "    ma20 = ind.ma(c, 20).to_numpy()"
    },
    {
      "number": 132,
      "text": "    d_min = int(CFG_ZT.get(\"pullback_days_min\", 2))"
    },
    {
      "number": 133,
      "text": "    d_max = int(CFG_ZT.get(\"pullback_days_max\", 7))"
    },
    {
      "number": 134,
      "text": "    shrink = float(CFG_ZT.get(\"volume_shrink_ratio\", 0.7))"
    },
    {
      "number": 135,
      "text": "    n = len(df)"
    },
    {
      "number": 136,
      "text": "    for i in range(25, n):"
    },
    {
      "number": 137,
      "text": "        for back in range(d_min, d_max + 1):"
    },
    {
      "number": 138,
      "text": "            j = i - back"
    },
    {
      "number": 139,
      "text": "            if j < 0 or not zt[j]:"
    },
    {
      "number": 140,
      "text": "                continue"
    },
    {
      "number": 141,
      "text": "            # 回踩期最低价不破涨停日最低价（不破涨停板支撑）"
    },
    {
      "number": 142,
      "text": "            if lo.iloc[j + 1:i + 1].min() < lo.iloc[j]:"
    },
    {
      "number": 143,
      "text": "                continue"
    },
    {
      "number": 144,
      "text": "            if c.iloc[i] >= ma5[i] and c.iloc[i] >= ma20[i] and vol_ratio[i] < shrink:"
    },
    {
      "number": 145,
      "text": "                out.iloc[i] = True"
    },
    {
      "number": 146,
      "text": "                break"
    },
    {
      "number": 147,
      "text": "    return out"
    },
    {
      "number": 148,
      "text": ""
    },
