    },
    {
      "number": 150,
      "text": "def detect_fanbao(df: pd.DataFrame, overrides: dict | None = None) -> pd.Series:"
    },
    {
      "number": 151,
      "text": "    \"\"\"趋势反包：昨日阴线，今日阳线收盘包住昨日最高，量能同比放大"
    },
    {
      "number": 152,
      "text": "    （v4.0.1 修正：支持高开反包，不再要求开盘低于昨收——中京电子/圣泉集团案例均为高开拉升反包）"
    },
    {
      "number": 153,
      "text": ""
    },
    {
      "number": 154,
      "text": "    overrides:"
    },
    {
      "number": 155,
      "text": "      max_gain_pct: 反包日收盘涨幅上限（%）。None=不过滤。"
    },
    {
      "number": 156,
      "text": "        ⚠️ 2026-08-25 全池 5353 信号验证：反包日涨幅 6%+ 组后5日 +1.65%（胜率53%）"
    },
    {
      "number": 157,
      "text": "        > 0~2% 组 +0.35% —— 高涨幅组反而更好，勿加低涨幅过滤（12 笔回测样本的"
    },
    {
      "number": 158,
      "text": "        反直觉结论已被信号级大样本推翻，属过拟合）。"
    },
    {
      "number": 159,
      "text": "      above_ma: 要求收盘站上 N 日均线（趋势反包语境，0=不要求）"
    },
    {
      "number": 160,
      "text": "    \"\"\""
    },
    {
      "number": 161,
      "text": "    out = pd.Series(False, index=df.index)"
    },
    {
      "number": 162,
      "text": "    if not _require(df, 10):"
    },
    {
      "number": 163,
      "text": "        return out"
    },
    {
      "number": 164,
      "text": "    o = dict(overrides or {})"
    },
    {
      "number": 165,
      "text": "    max_gain = o.get(\"max_gain_pct\")"
    },
    {
      "number": 166,
      "text": "    above_ma = int(o.get(\"above_ma\", 0))"
    },
    {
      "number": 167,
      "text": "    bear = ind.is_bearish(df).to_numpy()"
    },
    {
      "number": 168,
      "text": "    bull = ind.is_bullish(df).to_numpy()"
    },
    {
      "number": 169,
      "text": "    c, hi = df[\"close\"], df[\"high\"]"
    },
    {
      "number": 170,
      "text": "    v = df[\"volume\"]"
    },
    {
      "number": 171,
      "text": "    n = len(df)"
    },
    {
      "number": 172,
      "text": "    ma_n = ind.ma(c, above_ma).to_numpy() if above_ma > 0 else None"
    },
    {
      "number": 173,
      "text": "    for i in range(1, n):"
    },
    {
      "number": 174,
      "text": "        if bear[i - 1] and bull[i]:"
    },
    {
      "number": 175,
      "text": "            if c.iloc[i] > hi.iloc[i - 1]:"
    },
    {
      "number": 176,
      "text": "                if v.iloc[i] > v.iloc[i - 1]:  # 同比放量（v22 图上标注口径）"
    },
    {
      "number": 177,
      "text": "                    if max_gain is not None and c.iloc[i] / c.iloc[i - 1] - 1 > max_gain / 100.0:"
    },
    {
      "number": 178,
      "text": "                        continue"
    },
    {
      "number": 179,
      "text": "                    if ma_n is not None and c.iloc[i] < ma_n[i]:"
    },
    {
      "number": 180,
      "text": "                        continue"
    },
    {
      "number": 181,
      "text": "                    out.iloc[i] = True"
    },
    {
      "number": 182,
      "text": "    return out"
    },
    {
      "number": 183,
      "text": ""
    },
