    {
      "number": 185,
      "text": "def detect_xianren(df: pd.DataFrame, with_confirm: bool = True) -> pd.Series:"
    },
    {
      "number": 186,
      "text": "    \"\"\"仙人指路：公式日（长上影+趋势+量能+位置）+ 可选次日/第三日反包确认"
    },
    {
      "number": 187,
      "text": "    with_confirm=True 时信号日 = 确认日（放量阳线吃掉上影高点）\"\"\""
    },
    {
      "number": 188,
      "text": "    out = pd.Series(False, index=df.index)"
    },
    {
      "number": 189,
      "text": "    if not _require(df, 70):"
    },
    {
      "number": 190,
      "text": "        return out"
    },
    {
      "number": 191,
      "text": "    c, o, hi, lo = df[\"close\"], df[\"open\"], df[\"high\"], df[\"low\"]"
    },
    {
      "number": 192,
      "text": "    v = df[\"volume\"]"
    },
    {
      "number": 193,
      "text": "    n = len(df)"
    },
    {
      "number": 194,
      "text": "    body = ind.body(df).to_numpy()"
    },
    {
      "number": 195,
      "text": "    upsh = ind.upper_shadow(df).to_numpy()"
    },
    {
      "number": 196,
      "text": "    ma60 = ind.ma(c, 60).to_numpy()"
    },
    {
      "number": 197,
      "text": "    v5 = v.rolling(5).mean().to_numpy()"
    },
    {
      "number": 198,
      "text": "    xr_min = float(CFG_XR.get(\"upper_shadow_min_pct\", 2.8))"
    },
    {
      "number": 199,
      "text": "    xr_ratio = float(CFG_XR.get(\"upper_shadow_ratio\", 2.0))"
    },
    {
      "number": 200,
      "text": "    pos_min = float(CFG_XR.get(\"position_min\", 0.85))"
    },
    {
      "number": 201,
      "text": "    pos_max = float(CFG_XR.get(\"position_max\", 1.35))"
    },
    {
      "number": 202,
      "text": "    formula_day = pd.Series(False, index=df.index)"
    },
    {
      "number": 203,
      "text": "    for i in range(65, n):"
    },
    {
      "number": 204,
      "text": "        if body[i] <= 0:"
    },
    {
      "number": 205,
      "text": "            continue"
    },
    {
      "number": 206,
      "text": "        if upsh[i] < xr_ratio * body[i]:"
    },
    {
      "number": 207,
      "text": "            continue"
    },
    {
      "number": 208,
      "text": "        if upsh[i] / c.iloc[i - 1] * 100 < xr_min:"
    },
    {
      "number": 209,
      "text": "            continue"
    },
    {
      "number": 210,
      "text": "        if c.iloc[i] <= ma60[i] or ma60[i] <= ma60[i - 5]:"
    },
    {
      "number": 211,
      "text": "            continue"
    },
    {
      "number": 212,
      "text": "        if v.iloc[i] <= v5[i]:"
    },
    {
      "number": 213,
      "text": "            continue"
    },
    {
      "number": 214,
      "text": "        ratio = c.iloc[i] / c.iloc[i - 60]"
    },
    {
      "number": 215,
      "text": "        if not (pos_min < ratio < pos_max):"
    },
    {
      "number": 216,
      "text": "            continue"
    },
    {
      "number": 217,
      "text": "        formula_day.iloc[i] = True"
    },
    {
      "number": 218,
      "text": "    if not with_confirm:"
    },
    {
      "number": 219,
      "text": "        return formula_day"
    },
    {
      "number": 220,
      "text": "    # 确认：公式日之后 1~2 天内，放量阳线收盘吃掉公式日最高价"
    },
    {
      "number": 221,
      "text": "    fdays = df.index[formula_day.to_numpy()]"
    },
    {
      "number": 222,
      "text": "    for i in fdays:"
    },
    {
      "number": 223,
      "text": "        for k in (1, 2):"
    },
    {
      "number": 224,
      "text": "            j = i + k"
    },
    {
      "number": 225,
      "text": "            if j >= n:"
    },
    {
      "number": 226,
      "text": "                break"
    },
    {
      "number": 227,
      "text": "            if (c.iloc[j] > hi.iloc[i] and v.iloc[j] > v.iloc[i]"
    },
    {
      "number": 228,
      "text": "                    and c.iloc[j] > o.iloc[j]):"
    },
    {
      "number": 229,
      "text": "                out.iloc[j] = True"
    },
    {
      "number": 230,
      "text": "                break"
    },
    {
      "number": 231,
      "text": "    return out"
    },
    {
