      "text": "    vma5 = _vol_ma(df, 5).to_numpy()"
    },
    {
      "number": 268,
      "text": "    vma20 = _vol_ma(df, 20).to_numpy()"
    },
    {
      "number": 269,
      "text": "    # 一字板近似（排除弱势用）"
    },
    {
      "number": 270,
      "text": "    yizi = ((hi.to_numpy() - lo.to_numpy()) <= 0.001) & ((c.to_numpy() / pd.Series(c).shift(1).to_numpy() - 1) > 0.09)"
    },
    {
      "number":lb 根均量 × vol_mult 且收上均价线）"
    },
    {
      "number": 79,
      "text": "    vol_ma = v.rolling(lb).mean().shift(1)"
    },
    {
      "number": 80,
      "text": "    surge_mid = (v > vol_ma * vol_mult) & (df[\"close\"] > vwap)"
    },
    {
      "number": 81,
      "text": "    # 开盘放量（前 open_win 分钟：量 > 首根竞价量 × open_mult）"
    },
    {
      "number": 82,
      "text": "    first_vol = float(v.iloc[0]) if v.iloc[0] > 0 else float(v.iloc[1:].mean())"
    },
    {
      "number": 83,
      "text": "    open_surge = pd.Series(False, index=df.index)"
    },
    {
      "number": 84,
      "text": "    open_surge.iloc[:open_win] = (v.iloc[:open_win] > first_vol * open_mult).to_numpy()"
    },
    {
      "number": 85,
      "text": "    surge = (surge_mid | open_surge) & in_win"
    },
    {
      "number": 86,
      "text": ""
    },
    {
      "number": 87,
      "text": "    # ① 白线向上：VWAP 高于过去 lb 分钟最低 VWAP（开盘阶段退化为 vs 首根）"
    },
    {
      "number": 88,
      "text": "    vwap_floor = vwap.rolling(lb).min().shift(1).fillna(vwap.iloc[0])"
    },
    {
      "number": 89,
      "text": "    vwap_up = vwap > vwap_floor * (1 + vwap_eps)"
    },
    {
      "number": 90,
      "text": ""
    },
    {
      "number": 91,
      "text": "    # 回踩：low 触及 VWAP 但不破；站稳：收上 VWAP 且 low 不破"
    },
    {
      "number": 92,
      "text": "    hold = df[\"low\"] >= vwap * (1 - tol)"
    },
    {
      "number": 93,
      "text": "    reclaim = (df[\"close\"] > vwap) & hold"
    },
    {
      "number": 94,
      "text": ""
    },
    {
      "number": 95,
      "text": "    pct = df[\"close\"] / prev_close - 1"
    },
    {
      "number": 96,
      "text": "    pct_ok = (pct <= max_pct) & (pct >= -0.05)"
    },
    {
      "number": 97,
      "text": ""
    },
    {
      "number": 98,
      "text": "    # B1 开盘强势（开盘窗口内放量且未破均价线）"
    },
    {
      "number": 99,
      "text": "    open_zone = pd.Series(False, index=df.index)"
    },
    {
      "number": 100,
      "text": "    open_zone.iloc[:open_win] = True"
    },
    {
      "number": 101,
      "text": "    b1 = surge & open_zone & hold & vwap_up & pct_ok"
    },
    {
      "number": 102,
      "text": "    # B2 回踩确认：surge_win 根内有放量拉升，当前回踩后重新站稳（1m=60 根≈60 分钟；5m=12 根）"
    },
    {
      "number": 103,
      "text": "    had_surge = surge.rolling(surge_win, min_periods=1).max().shift(1).fillna(False).astype(bool)"
    },
    {
      "number": 104,
      "text": "    b2 = reclaim & had_surge & vwap_up & pct_ok & in_win & ~open_zone"
    },
    {
      "number": 105,
      "text": ""
    },
    {
      "number": 106,
      "text": "    b = (b1 | b2).to_numpy()"
    },
    {
      "number": 107,
      "text": "    # 冷却合并：同波拉升只取首个触发"
    },
    {
      "number": 108,
      "text": "    merged = []"
    },
    {
      "number": 109,
      "text": "    last = -10**9"
    },
    {
      "number": 110,
      "text": "    for i in range(len(b)):"
    },
    {
      "number": 111,
      "text": "        if b[i] and i - last >= cool_min:"
    },
    {
      "number": 112,
      "text": "            merged.append(i)"
    },
    {
      "number": 113,
      "text": "            last = i"
    },
    {
      "number": 114,
      "text": ""
    },
    {
      "number": 115,
      "text": "    close_arr = df[\"close\"].to_numpy()"
    },
    {
      "number": 116,
      "text": "    vwap_arr = vwap.to_numpy()"
    },
    {
      "number": 117,
      "text": "    rows = []"
    },
    {
      "number": 118,
      "text": "    for i in merged:"
    },
    {
      "number": 119,
      "text": "        rows.append({"
    },
    {
      "number": 120,
      "text": "            \"ts\": str(df[\"ts\"].iloc[i]),"
