  "entry": [
    {
      "number": 1,
      "text": "\"\"\"P4 每日盘后信号管线"
    },
    {
      "number": 2,
      "text": ""
    },
    {
      "number": 3,
      "text": "流程: 数据更新(--update) → 环境打分(简版) → 全池五大战法扫描(当日信号) → 信号报告(md+html)"
    },
    {
      "number": 4,
      "text": ""
    },
    {
      "number": 5,
      "text": "用法:"
    },
    {
      "number": 6,
      "text": "    python scripts/daily_pipeline.py                  # 用 DB 最新交易日"
    },
    {
      "number": 7,
      "text": "    python scripts/daily_pipeline.py --date 2026-08-21"
    },
    {
      "number": 8,
      "text": "    python scripts/daily_pipeline.py --update         # 先增量更新数据再扫描"
    },
    {
      "number": 9,
      "text": "输出: outputs/signals/YYYY-MM-DD_signal_report.md / .html"
    },
    {
      "number": 10,
      "text": "\"\"\""
    },
    {
      "number": 11,
      "text": "from __future__ import annotations"
    },
    {
      "number": 12,
      "text": ""
    },
    {
      "number": 13,
      "text": "import argparse"
    },
    {
      "number": 14,
      "text": "import datetime as dt"
    },
    {
      "number": 15,
      "text": "import json"
    },
    {
      "number": 16,
      "text": "import pathlib"
    },
    {
      "number": 17,
      "text": "import sys"
    },
    {
      "number": 18,
      "text": ""
    },
    {
      "number": 19,
      "text": "import pandas as pd"
    },
    {
      "number": 20,
      "text": ""
    },
    {
      "number": 21,
      "text": "ROOT = pathlib.Path(__file__).resolve().parent.parent"
    },
    {
      "number": 22,
      "text": "sys.path.insert(0, str(ROOT / \"src\"))"
    },
    {
      "number": 23,
      "text": "sys.path.insert(0, str(ROOT))"
    },
    {
      "number": 24,
      "text": ""
    },
    {
      "number": 25,
      "text": "from data.store import Store  # noqa: E402"
    },
    {
      "number": 26,
      "text": "from core import strategies as S  # noqa: E402"
    },
    {
      "number": 27,
      "text": "from core import indicators as ind  # noqa: E402"
    },
    {
      "number": 28,
      "text": "from core.env_score import env_score, env_score_full, regime_from_simple  # noqa: E402"
    },
    {
      "number": 29,
      "text": "from core.names import stock_names  # noqa: E402"
    },
    {
      "number": 30,
      "text": "from report.md2html import md_file2html  # noqa: E402"
    },
    {
      "number": 31,
      "text": ""
    },
    {
      "number": 32,
      "text": "SIGNAL_DIR = ROOT / \"outputs\" / \"signals\""
    },
    {
      "number": 33,
      "text": ""
    },
    {
      "number": 34,
      "text": ""
    },
    {
      "number": 35,
      "text": "def rows_to_df(rows) -> pd.DataFrame:"
    },
    {
      "number": 36,
      "text": "    cols = [\"symbol\", \"date\", \"open\", \"high\", \"low\", \"close\", \"volume\", \"amount\"]"
    },
    {
      "number": 37,
      "text": "    df = pd.DataFrame(rows, columns=cols[:len(rows[0])])"
    },
    {
      "number": 38,
      "text": "    for c in (\"open\", \"high\", \"low\", \"close\", \"volume\", \"amount\"):"
    },
    {
      "number": 39,
      "text": "        df[c] = pd.to_numeric(df[c], errors=\"coerce\")"
    },
    {
      "number": 40,
      "text": "    df[\"date\"] = df[\"date\"].astype(str)"
    },
    {
      "number": 41,
      "text": "    return df.reset_index(drop=True)"
    },
    {
      "number": 42,
      "text": ""
    },
    {
      "number": 43,
      "text": ""
    },
    {
      "number": 44,
      "text": "DETECTORS = {"
    },
    {
      "number": 45,
      "text": "    \"上升回档\": lambda df: S.detect_huigui(df, mode=\"live\"),"
    },
    {
      "number": 46,
      "text": "    \"涨停回踩\": lambda df: S.detect_zt_huicai(df),"
    },
    {
      "number": 47,
      "text": "    \"趋势反包\": lambda df: S.detect_fanbao(df),"
    },
    {
      "number": 48,
      "text": "    \"仙人指路\": lambda df: S.detect_xianren(df, with_confirm=True),"
    },
    {
      "number": 49,
      "text": "}"
    },
    {
      "number": 50,
      "text": ""
    },
    {
      "number": 51,
      "text": ""
    },
    {
      "number": 52,
      "text": "def latest_trading_day(store: Store) -> str:"
    },
    {
      "number": 53,
      "text": "    r = store.conn.execute(\"SELECT MAX(date) FROM index_daily\").fetchone()"
    },
    {
      "number": 54,
      "text": "    return r[0] if r and r[0] else dt.date.today().isoformat()"
    },
    {
      "number": 55,
      "text": ""
    },
    {
      "number": 56,
      "text": ""
    },
    {
      "number": 57,
      "text": "def update_data(store: Store):"
    },
    {
      "number": 58,
      "text": "    \"\"\"增量更新：指数 + 全股票池（东财限流时自动回退新浪/腾讯）\"\"\""
    },
    {
      "number": 59,
      "text": "    from data import fetchers as F"
    },
    {
      "number": 60,
      "text": ""
    },
    {
      "number": 61,
      "text": "    print(\"== 增量更新 ==\")"
    },
    {
      "number": 62,
      "text": "    for sym in F.index_symbols():"
    },
    {
      "number": 63,
      "text": "        try:"
    },
    {
      "number": 64,
      "text": "            df = F.fetch_index_daily(sym)"
    },
    {
      "number": 65,
      "text": "            if not df.empty:"
    },
    {
      "number": 66,
      "text": "                store.upsert_index_daily(df, sym)"
    },
    {
      "number": 67,
      "text": "        except Exception as e:  # noqa: BLE001"
    },
    {
      "number": 68,
      "text": "            print(f\"  index {sym}: FAIL {type(e).__name__} {str(e)[:80]}\")"
    },
    {
      "number": 69,
      "text": "    rows = store.conn.execute(\"SELECT DISTINCT symbol FROM stock_daily\").fetchall()"
    },
    {
      "number": 70,
      "text": "    symbols = [r[0] for r in rows]"
    },
    {
      "number": 71,
      "text": "    last = dict(store.conn.execute("
    },
    {
      "number": 72,
      "text": "        \"SELECT symbol, MAX(date) FROM stock_daily GROUP BY symbol\").fetchall())"
    },
    {
      "number": 73,
      "text": "    for sym in symbols:"
    },
    {
      "number": 74,
      "text": "        start = last.get(sym, \"2022-01-01\")"
    },
    {
      "number": 75,
      "text": "        try:"
    },
    {
      "number": 76,
      "text": "            df = F.fetch_stock_daily(sym, start, \"20261231\")"
    },
    {
      "number": 77,
      "text": "            if not df.empty:"
    },
    {
      "number": 78,
      "text": "                df = df[df[\"date\"] >= start]"
    },
    {
      "number": 79,
      "text": "                store.upsert_stock_daily(df, sym)"
    },
    {
      "number": 80,
      "text": "        except Exception as e:  # noqa: BLE001"
    },
    {
      "number": 81,
      "text": "            print(f\"  {sym}: FAIL {type(e).__name__} {str(e)[:80]}\")"
    },
    {
      "number": 82,
      "text": ""
    },
    {
      "number": 83,
      "text": ""
    },
    {
      "number": 84,
      "text": "def main():"
    },
    {
      "number": 85,
      "text": "    ap = argparse.ArgumentParser(description=\"每日盘后信号管线\")"
    },
    {
      "number": 86,
      "text": "    ap.add_argument(\"--date\", default=\"\", help=\"目标日期（默认 DB 最新交易日）\")"
