      "number": 1,
      "text": "\"\"\"Deterministic EvoAlpha team coordinator for paper-trading decisions."
    },
    {
      "number": 2,
      "text": ""
    },
    {
      "number": 3,
      "text": "The model runtime may provide role opinions, but this module owns the final"
    },
    {
      "number": 4,
      "text": "contract checks and risk gate. It never submits real orders."
    },
    {
      "number": 5,
      "text": "\"\"\""
    },
    {
      "number": 6,
      "text": "from __future__ import annotations"
    },
    {
      "number": 7,
      "text": ""
    },
    {
      "number": 8,
      "text": "import argparse"
    },
    {
      "number": 9,
      "text": "import datetime as dt"
    },
    {
      "number": 10,
      "text": "import json"
    },
    {
      "number": 11,
      "text": "import pathlib"
    },
    {
      "number": 12,
      "text": "import sys"
    },
    {
      "number": 13,
      "text": "import tempfile"
    },
    {
      "number": 14,
      "text": ""
    },
    {
      "number": 15,
      "text": "ROOT = pathlib.Path(__file__).resolve().parent.parent"
    },
    {
      "number": 16,
      "text": "CONTRACT = ROOT / \"agents\" / \"artifact-contract.v1.json\""
    },
    {
      "number": 17,
      "text": "REQUIRED_ROLES = ["
    },
    {
      "number": 18,
      "text": "    \"researcher\","
    },
    {
      "number": 19,
      "text": "    \"strategy_researcher\","
    },
    {
      "number": 20,
      "text": "    \"trader\","
    },
    {
      "number": 21,
      "text": "    \"portfolio_manager\","
    },
    {
      "number": 22,
      "text": "    \"risk_manager\","
    },
    {
      "number": 23,
      "text": "    \"coordinator\","
    },
    {
      "number": 24,
      "text": "]"
    },
    {
      "number": 25,
      "text": ""
    },
    {
      "number": 26,
      "text": ""
    },
    {
      "number": 27,
      "text": "def load_payload(path: pathlib.Path) -> dict:"
    },
    {
      "number": 28,
      "text": "    with path.open(encoding=\"utf-8\") as handle:"
    },
    {
      "number": 29,
      "text": "        payload = json.load(handle)"
    },
    {
      "number": 30,
      "text": "    if not isinstance(payload, dict):"
    },
    {
      "number": 31,
      "text": "        raise ValueError(\"team input must be a JSON object\")"
    },
    {
      "number": 32,
      "text": "    return payload"
    },
    {
      "number": 33,
      "text": ""
    },
    {
      "number": 34,
      "text": ""
    },
    {
      "number": 35,
      "text": "def coordinate(payload: dict) -> dict:"
    },
    {
      "number": 36,
      "text": "    roles = payload.get(\"roles\", {})"
    },
    {
      "number": 37,
      "text": "    if not isinstance(roles, dict):"
    },
    {
      "number": 38,
      "text": "        roles = {}"
    },
    {
      "number": 39,
      "text": "    missing = [role for role in REQUIRED_ROLES if not isinstance(roles.get(role), dict)]"
    },
    {
      "number": 40,
      "text": "    risk = roles.get(\"risk_manager\") if isinstance(roles.get(\"risk_manager\"), dict) else {}"
    },
    {
      "number": 41,
      "text": "    blocks = list(payload.get(\"blocking_reasons\", [])) if isinstance(payload.get(\"blocking_reasons\", []), list) else []"
    },
    {
      "number": 42,
      "text": "    blocks.extend(risk.get(\"blocking_reasons\", []))"
    },
    {
      "number": 43,
      "text": "    risk_status = str(risk.get(\"risk_status\", \"unknown\"))"
    },
    {
      "number": 44,
      "text": "    if risk_status in {\"blocked\", \"fail\", \"failed\"}:"
    },
    {
      "number": 45,
      "text": "        blocks.append(f\"risk_manager status={risk_status}\")"
    },
    {
      "number": 46,
      "text": "    if missing:"
    },
    {
      "number": 47,
      "text": "        blocks.append(\"missing roles: \" + \", \".join(missing))"
    },
    {
      "number": 48,
      "text": "    decision = \"blocked\" if blocks else \"paper_execute\""
    },
    {
      "number": 49,
      "text": "    return {"
    },
    {
      "number": 50,
      "text": "        \"schema_version\": \"evoalpha.team-decision.v1\","
    },
    {
      "number": 51,
      "text": "        \"run_id\": str(payload.get(\"run_id\", \"\")),"
    },
    {
      "number": 52,
      "text": "        \"as_of\": str(payload.get(\"as_of\", dt.date.today().isoformat())),"
    },
    {
      "number": 53,
      "text": "        \"mode\": \"paper_only\","
    },
    {
      "number": 54,
      "text": "        \"decision\": decision,"
    },
    {
      "number": 55,
      "text": "        \"roles_present\": sorted(roles),"
    },
    {
      "number": 56,
      "text": "        \"required_roles\": REQUIRED_ROLES,"
    },
    {
      "number": 57,
      "text": "        \"risk_status\": risk_status,"
    },
    {
      "number": 58,
      "text": "        \"blocking_reasons\": blocks,"
    },
    {
      "number": 59,
      "text": "        \"orders\": [] if decision == \"blocked\" else payload.get(\"orders\", []),"
    },
    {
      "number": 60,
      "text": "        \"real_order_submission\": False,"
    },
    {
      "number": 61,
      "text": "        \"created_at\": dt.datetime.now(dt.timezone.utc).isoformat(),"
    },
    {
      "number": 62,
      "text": "    }"
    },
    {
      "number": 63,
      "text": ""
    },
    {
      "number": 64,
      "text": ""
    },
    {
      "number": 65,
      "text": "def persist(path: pathlib.Path, encoded: str) -> None:"
    },
    {
      "number": 66,
      "text": "    path.parent.mkdir(parents=True, exist_ok=True)"
    },
    {
      "number": 67,
      "text": "    with tempfile.NamedTemporaryFile(\"w\", encoding=\"utf-8\", dir=path.parent, delete=False, suffix=\".tmp\") as handle:"
    },
    {
      "number": 68,
      "text": "        handle.write(encoded)"
    },
    {
      "number": 69,
      "text": "        handle.flush()"
    },
    {
      "number": 70,
      "text": "        temp = pathlib.Path(handle.name)"
    },
    {
      "number": 71,
      "text": "    temp.replace(path)"
    },
    {
      "number": 72,
      "text": ""
    },
    {
      "number": 73,
      "text": ""
    },
    {
      "number": 74,
      "text": "def main() -> int:"
    },
    {
      "number": 75,
      "text": "    parser = argparse.ArgumentParser(description=\"Coordinate EvoAlpha paper-trading role artifacts\")"
    },
    {
      "number": 76,
      "text": "    parser.add_argument(\"input\", type=pathlib.Path, help=\"team input JSON\")"
    },
    {
      "number": 77,
      "text": "    parser.add_argument(\"--output\", type=pathlib.Path, help=\"write decision JSON\")"
    },
    {
      "number": 78,
      "text": "    args = parser.parse_args()"
    },
    {
      "number": 79,
      "text": "    result = coordinate(load_payload(args.input))"
    },
    {
      "number": 80,
      "text": "    encoded = json.dumps(result, ensure_ascii=False, indent=2) + \"\\\\n\""
    },
    {
      "number": 81,
      "text": "    output = args.output"
    },
    {
      "number": 82,
      "text": "    if output is None:"
    },
    {
      "number": 83,
      "text": "        run_id = result[\"run_id\"] or dt.datetime.now().strftime(\"run-%Y%m%dT%H%M%S\")"
    },
    {
      "number": 84,
      "text": "        output = ROOT / \"outputs\" / \"team_decisions\" / f\"{run_id}.json\""
    },
    {
      "number": 85,
      "text": "    persist(output, encoded)"
    },
    {
      "number": 86,
      "text": "    print(f\"decision={result['decision']} output={output}\")"
    },
    {
      "number": 87,
      "text": "    return 0 if result[\"decision\"] == \"paper_execute\" else 2"
    },
    {
      "number": 88,
      "text": ""
    },
    {
      "number": 89,
      "text": ""
    },
    {
      "number": 90,
      "text": "if __name__ == \"__main__\":"
    },
    {
      "number": 91,
      "text": "    raise SystemExit(main())"
    }
  ]
}

