{"code": "const cmd = @"
$ErrorActionPreference='Stop'
$ws='C:\Users\YZP\WorkBuddy\Claw\方法论与研究文档'
$out='C:\Users\YZP\WorkBuddy\Claw\方法论与研究文档-非EvoAlpha'
New-Item -ItemType Directory -Force -Path $out | Out-Null
# Unrelated directories
foreach($d in @('分析框架','研究报告','_review_tmp','.pip_tmp','yaoban_tasks')){
  if(Test-Path (Join-Path $ws $d)){ Move-Item -LiteralPath (Join-Path $ws $d) -Destination $out -Force }
}
# Mangled debris files at workspace root
$debris = @('UsersYZPWorkBuddyyaoban_tasksrun_cand_shim.ps1','UsersYZPWorkBuddyyaoban_tasksrun_daily_shim.ps1','UsersYZPWorkBuddyyaoban_tasksrun_loop_shim.ps1','UsersYZPWorkBuddyyaoban_tasksrun_tick_shim.ps1','UsersYZPWorkBuddyyaoban_tasks_vbs_testout.txt')
foreach($f in $debris){ if(Test-Path (Join-Path $ws $f)){ Move-Item -LiteralPath (Join-Path $ws $f) -Destination $out -Force } }
# Vibe install artifacts -> EvoAlpha archive
$arch=Join-Path $ws 'EvoAlpha\archive\vibe-source'
New-Item -ItemType Directory -Force -Path $arch | Out-Null
foreach($f in @('vibe.tar.gz','Vibe-Research-tree.json','Vibe-Research-README.md')){
  if(Test-Path (Join-Path $ws $f)){ Move-Item -LiteralPath (Join-Path $ws $f) -Destination $arch -Force }
}
Write-Output '--- 方法论与研究文档 now ---'
Get-ChildItem -Force $ws | Select-Object Name | Format-Table -AutoSize
Write-Output '--- new folder ---'
Get-ChildItem -Force $out | Select-Object Name | Format-Table -AutoSize
