--- ensure script ---
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$yaoban = Split-Path -Parent $root
$yaoban = Join-Path $yaoban 'yaoban-system'
$node = (Get-Command node.exe).Source
$python = 'C:\Users\YZP\.workbuddy\binaries\python\envs\default\Scripts\python.exe'
$logDir = Join-Path $root 'validation\services'
New-Item -ItemType Directory -Force -Path $logDir | Out-Null

function Test-Http([string]$url, [int[]]$accepted = @(200)) {
    try {
        $response = Invoke-WebRequest -UseBasicParsing -Uri $url -TimeoutSec 3
        return $accepted -contains [int]$response.StatusCode
    } catch {
        if ($_.Exception.Response -and $accepted -contains [int]$_.Exception.Response.StatusCode) { return $true }
        return $false
    }
}

function Wait-Http([string]$url, [int[]]$accepted = @(200)) {
    for ($attempt = 0; $attempt -lt 30; $attempt += 1) {
        if (Test-Http $url $accepted) { return }
        Start-Sleep -Milliseconds 500
    }
    throw "service did not become ready: $url"
}

if (-not (Test-Http 'http://127.0.0.1:8766/health' @(200, 401))) {
    $keyFile = Join-Path $root '.local\deepseek.key'
    if (-not (Test-Path -LiteralPath $keyFile)) { throw 'local DeepSeek credential file is missing' }
    $previousKey = $env:DEEPSEEK_API_KEY
    try {
        $env:DEEPSEEK_API_KEY = (Get-Content -LiteralPath $keyFile -Raw).Trim()
        Start-Process -FilePath $node -ArgumentList @('src/api.ts', '--port', '8766') `
            -WorkingDirectory (Join-Path $root 'orchestrator') -WindowStyle Hidden `
            -RedirectStandardOutput (Join-Path $logDir 'orchestrator.log') `
            -RedirectStandardError (Join-Path $logDir 'orchestrator.stderr.log')
    } finally {
        $env:DEEPSEEK_API_KEY = $previousKey
    }
    Wait-Http 'http://127.0.0.1:8766/health' @(200, 401)
}

if (-not (Test-Http 'http://127.0.0.1:5930/')) {
    Start-Process -FilePath $node -ArgumentList @('node_modules/vite/bin/vite.js', '--host', '127.0.0.1', '--port', '5930') `
        -WorkingDirectory (Join-Path $root 'desktop') -WindowStyle Hidden `
        -RedirectStandardOutput (Join-Path $logDir 'desktop.log') `
        -RedirectStandardError (Join-Path $logDir 'desktop.stderr.log')
    Wait-Http 'http://127.0.0.1:5930/'
}

if (-not (Test-Http 'http://127.0.0.1:8765/board.json')) {
    Start-Process -FilePath $python -ArgumentList @('scripts/board_server.py', '--port', '8765') `
        -WorkingDirectory $yaoban -WindowStyle Hidden `
        -RedirectStandardOutput (Join-Path $logDir 'fallback.log') `
        -RedirectStandardError (Join-Path $logDir 'fallback.stderr.log')
    Wait-Http 'http://127.0.0.1:8765/board.json'
}

$contractReady = $false
for ($attempt = 0; $attempt -lt 30; $attempt += 1) {
    try {
        $health = Invoke-RestMethod -Uri 'http://127.0.0.1:5930/api/health' -TimeoutSec 3
        $legacy = Invoke-RestMethod -Uri 'http://127.0.0.1:8765/board.json' -TimeoutSec 3
        $contractReady = $health.runtime -eq 'function_calling' `
            -and $health.provider_profile -eq 'deepseek' `
            -and $health.fallback.transparent_vr_api -eq $false `
            -and $legacy -is [pscustomobject]
        if ($contractReady) { break }
    } catch {
        # The Vite root can answer before its API proxy is ready; retry the full contract.
    }
    Start-Sleep -Milliseconds 500
}
if (-not $contractReady) { throw 'dashboard or legacy service contract mismatch' }

